/*__ESM_BODY_START__*/window.process={};import{r as reactExports,j as jsxRuntimeExports}from"./dashboard.jsdbx";import{i as insertStyle,N as NavHeader}from"./NavHeader.jsdbx";insertStyle('.fraud-app {
 min-height: 100vh;
 background: #0a0e14;
 color: #e2e8f0;
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.fraud-main {
 max-width: 1400px;
 margin: 0 auto;
 padding: 32px 40px;
}

/* Page Header */
.fraud-page-header {
 display: flex;
 justify-content: space-between;
 align-items: flex-start;
 margin-bottom: 32px;
}

.fraud-page-header__eyebrow {
 display: block;
 font-size: 11px;
 font-weight: 600;
 letter-spacing: 0.08em;
 text-transform: uppercase;
 color: #64748b;
 margin-bottom: 6px;
}

.fraud-page-header__title {
 font-size: 28px;
 font-weight: 700;
 color: #f1f5f9;
 margin: 0 0 8px 0;
}

.fraud-page-header__subtitle {
 font-size: 14px;
 color: #64748b;
 margin: 0;
 line-height: 1.5;
}

.fraud-page-header__right {
 display: flex;
 align-items: center;
}

.fraud-live-pill {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 20px;
 padding: 6px 14px;
 font-size: 12px;
 color: #94a3b8;
 font-weight: 500;
}

.fraud-live-pill__dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: #22c55e;
 flex-shrink: 0;
}

/* KPI Row */
.fraud-kpi-row {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 16px;
 margin-bottom: 36px;
}

.fraud-kpi-card {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 10px;
 padding: 20px 24px;
 display: flex;
 flex-direction: column;
 gap: 4px;
}

.fraud-kpi-card__label {
 font-size: 11px;
 font-weight: 600;
 letter-spacing: 0.06em;
 text-transform: uppercase;
 color: #64748b;
}

.fraud-kpi-card__value {
 font-size: 32px;
 font-weight: 700;
 color: #f1f5f9;
 font-variant-numeric: tabular-nums;
 margin: 6px 0 4px 0;
}

.fraud-kpi-card__value--red {
 color: #ef4444;
}

.fraud-kpi-card__value--amber {
 color: #f59e0b;
}

.fraud-kpi-card__caption {
 font-size: 12px;
 color: #64748b;
 line-height: 1.4;
}

/* Table Section */
.fraud-table-section {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 10px;
 overflow: hidden;
}

.fraud-table-header {
 display: flex;
 justify-content: space-between;
 align-items: flex-start;
 padding: 24px 24px 20px 24px;
 border-bottom: 1px solid #1a2035;
}

.fraud-table-header__title {
 font-size: 16px;
 font-weight: 600;
 color: #f1f5f9;
 margin: 0 0 4px 0;
}

.fraud-table-header__subtitle {
 font-size: 13px;
 color: #64748b;
 margin: 0;
 line-height: 1.4;
}

.fraud-model-pill {
 display: inline-flex;
 align-items: center;
 background: #1a2035;
 border: 1px solid #2a3045;
 border-radius: 16px;
 padding: 5px 12px;
 font-size: 12px;
 color: #94a3b8;
 font-weight: 500;
 white-space: nowrap;
}

/* Table */
.fraud-table-wrapper {
 overflow-x: auto;
}

.fraud-table {
 width: 100%;
 border-collapse: collapse;
 font-size: 13px;
}

.fraud-table thead th {
 text-align: left;
 padding: 12px 16px;
 font-size: 11px;
 font-weight: 600;
 letter-spacing: 0.05em;
 text-transform: uppercase;
 color: #64748b;
 border-bottom: 1px solid #1a2035;
 white-space: nowrap;
}

.fraud-table tbody tr {
 border-bottom: 1px solid #1a2035;
 transition: background 0.15s;
}

.fraud-table tbody tr:last-child {
 border-bottom: none;
}

.fraud-table tbody tr:hover {
 background: #0d1219;
}

.fraud-table tbody td {
 padding: 14px 16px;
 vertical-align: middle;
}

.fraud-table__primary {
 display: block;
 font-weight: 600;
 color: #e2e8f0;
 margin-bottom: 2px;
}

.fraud-table__secondary {
 display: block;
 font-size: 12px;
 color: #64748b;
}

.fraud-table__reason {
 color: #cbd5e1;
 font-style: normal;
 line-height: 1.4;
}

.fraud-table__refund {
 font-weight: 600;
 color: #e2e8f0;
 font-variant-numeric: tabular-nums;
}

/* Confidence */
.fraud-confidence {
 display: flex;
 flex-direction: column;
 gap: 6px;
 min-width: 100px;
}

.fraud-confidence__badge {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 font-size: 12px;
 font-weight: 600;
 padding: 2px 8px;
 border-radius: 4px;
 width: fit-content;
}

.fraud-confidence__bar-track {
 width: 100%;
 height: 4px;
 background: #1a2035;
 border-radius: 2px;
 overflow: hidden;
}

.fraud-confidence__bar-fill {
 height: 100%;
 border-radius: 2px;
 transition: width 0.3s ease;
}

/* Decision */
.fraud-decision-cell {
 display: flex;
 flex-direction: column;
 gap: 8px;
}

.fraud-decision-badge {
 display: inline-flex;
 align-items: center;
 font-size: 12px;
 font-weight: 500;
 padding: 4px 10px;
 border-radius: 4px;
 width: fit-content;
}

.decision--pending {
 background: #1e293b;
 color: #94a3b8;
}

.decision--escalated {
 background: rgba(245, 158, 11, 0.1019607843);
 color: #f59e0b;
}

.decision--denied {
 background: rgba(239, 68, 68, 0.1019607843);
 color: #ef4444;
}

.decision--approved {
 background: rgba(34, 197, 94, 0.1019607843);
 color: #22c55e;
}

/* Action Buttons */
.fraud-action-buttons {
 display: flex;
 gap: 6px;
}

.fraud-action-btn {
 font-size: 11px;
 font-weight: 500;
 padding: 4px 10px;
 border-radius: 4px;
 border: 1px solid #1a2035;
 background: transparent;
 cursor: pointer;
 transition: background 0.15s, border-color 0.15s;
}

.fraud-action-btn--approve {
 color: #22c55e;
 border-color: rgba(34, 197, 94, 0.2);
}

.fraud-action-btn--approve:hover {
 background: rgba(34, 197, 94, 0.1019607843);
 border-color: #22c55e;
}

.fraud-action-btn--escalate {
 color: #f59e0b;
 border-color: rgba(245, 158, 11, 0.2);
}

.fraud-action-btn--escalate:hover {
 background: rgba(245, 158, 11, 0.1019607843);
 border-color: #f59e0b;
}

.fraud-action-btn--deny {
 color: #ef4444;
 border-color: rgba(239, 68, 68, 0.2);
}

.fraud-action-btn--deny:hover {
 background: rgba(239, 68, 68, 0.1019607843);
 border-color: #ef4444;
